 	//sem_signal(d->mutex);

 /// @todo Gestire l'operazione tenendo conto della buffer cache.
-// ( SOLUZIONE 2023-01-11
-//   SOLUZIONE 2023-01-11 )
+
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		natl block = primo + i;
+		natb* dest = vetti + i * DIM_BLOCK;
+
+		// Search cache for this block
+		int found = -1;
+		for (int j = 0; j < MAX_BUF_DES; j++) {
+			if (d->bufcache[j].full && d->bufcache[j].block == block) {
+				found = j;
+				break;
+			}
+		}
+
+		if (found >= 0) {
+			// Cache hit: copy from cache and promote
+			memcpy(dest, d->bufcache[found].buf, DIM_BLOCK);
+			bufcache_promote(&d->bufcache[found]);
+		} else {
+			// Cache miss: find an empty slot or use LRU
+			int slot = -1;
+			for (int j = 0; j < MAX_BUF_DES; j++) {
+				if (!d->bufcache[j].full) {
+					slot = j;
+					break;
+				}
+			}
+			if (slot < 0) {
+				// No empty slot: evict LRU
+				slot = d->lru;
+			}
+
+			// Read the block from disk into the cache buffer
+			starthd_in(d, d->bufcache[slot].buf, block, 1);
+			sem_wait(d->sincr);
+
+			// Update cache entry
+			d->bufcache[slot].block = block;
+			d->bufcache[slot].full = true;
+
+			// Copy to destination
+			memcpy(dest, d->bufcache[slot].buf, DIM_BLOCK);
+
+			// Insert in LRU list
+			bufcache_promote(&d->bufcache[slot]);
+		}
+	}
+	sem_signal(d->mutex);
+
 //   ESAME 2023-01-11 ]
 }
