+		natl block = primo + i;
+		natb* src = vetto + i * DIM_BLOCK;
+
+		// Search cache for this block
+		int found = -1;
+		for (int j = 0; j < MAX_BUF_DES; j++) {
+			if (d->bufcache[j].full && d->bufcache[j].block == block) {
+				found = j;
+				break;
+			}
+		}
+
+		// Write through to disk
+		starthd_out(d, src, block, 1);
+		sem_wait(d->sincr);
+
+		if (found >= 0) {
+			// Cache hit: update cache and promote
+			memcpy(d->bufcache[found].buf, src, DIM_BLOCK);
+			bufcache_promote(&d->bufcache[found]);
+		}
+		// Cache miss (no-allocate): do not add to cache
+	}
+	sem_signal(d->mutex);
+
 //   ESAME 2023-01-11 ]
 }
 /// @}
@@ -734,8 +807,15 @@ bool hd_init()

 	hd::enable_intr();

-// ( SOLUZIONE 2023-01-11
-//   SOLUZIONE 2023-01-11 )
+	// Initialize buffer cache
+	d->lru = -1;
+	d->mru = -1;
+	d->io_count = 0;
+	for (int i = 0; i < MAX_BUF_DES; i++) {
+		d->bufcache[i].full = false;
+		d->bufcache[i].next = -1;
+		d->bufcache[i].prev = -1;
+	}

 	return true;
 }
